/* From Uiverse.io by ahmedyasserdev  - Tags: card, cool card, card hover */
.__UIV_SCOPE__ .unique-card {
  position: relative;
  width: 300px;
  height: 200px;
  overflow: hidden;
  border-radius: 15px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
  transition: transform 0.3s, box-shadow 0.3s;
}

.__UIV_SCOPE__ .unique-card:hover {
  transform: scale(1.1);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.3);
}

.__UIV_SCOPE__ .card-content {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  color: #888;
  z-index: 2;
  transition: color 0.3s;
}

.__UIV_SCOPE__ .unique-card:hover .card-content {
  color: #ff7e5f;
}

.__UIV_SCOPE__ .background-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(52, 73, 94, 0.7);
  border-radius: 15px;
  opacity: 0;
  transition: opacity 0.3s;
}

.__UIV_SCOPE__ .unique-card:hover .background-overlay {
  opacity: 1;
}

.__UIV_SCOPE__ .card-title {
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 10px;
}

.__UIV_SCOPE__ .card-description {
  font-size: 16px;
}
